AMAZING

I faced this erron when building stripe webhook with Next.js 14 app router.
In order to fix the issue, make sure to:
1. Use `request.text()` method for converting request body to string
2. Check whether you are passing correct webhook secret to `constructEvent()` function

my completed webhook (make sure to add logic for every event type):
```ts
import { NextResponse } from 'next/server';
import Stripe from 'stripe';
import { env } from '@/utils/utilities';
import { stripe } from '@/lib/stripe';

export async function POST(request: Request) {
  let event: Stripe.Event | null = null;

  try {
    // Read the raw request body as text
    const requestText = await request.text();
    // Retrieve the Stripe signature from the headers
    const sig = request.headers.get('stripe-signature');
    const signingSecret = process.env.STRIPE_WEBHOOK_SECRET as string;
    if (!sig) {
      console.error('Stripe signature is null');
      return NextResponse.json({ error: 'Webhook error' }, { status: 400 });
    }

    event = stripe.webhooks.constructEvent(requestText, sig, signingSecret);
  } catch (error) {
    if (error instanceof Error) {
      console.error('Webhook signature verification failed:', error);
      return NextResponse.json({ error: 'Webhook error' }, { status: 400 });
    }
  }

  // Handle the event
  if (event) {
    switch (event.type) {
      case 'checkout.session.completed':
        const completedSession = event.data.object;
        // Handle completed checkout session
        break;
      case 'checkout.session.async_payment_failed':
        const failedSession = event.data.object;
        // Handle failed checkout session
        break;
      default:
        // Unexpected event type
        console.log('Unhandled event type', event.type);
    }
  }

  return NextResponse.json({ received: true }, { status: 200 });
}
```

